<?php

namespace Database\Seeders;

use App\Enums\BagSize;
use App\Enums\ProcessMethod;
use App\Enums\ProductType;
use App\Models\FlavorNote;
use App\Models\Origin;
use App\Models\Product;
use App\Support\Catalog\DemoDataRules;
use Illuminate\Database\Seeder;
use Illuminate\Support\Collection;
use Illuminate\Support\Str;

/**
 * Products from 40 real CQI lots (database/data/cqi-selected.csv).
 * Origins, varieties, processes and cupping scores are real; flavor notes, roast level,
 * prices, stock and roast dates are DEMO DATA generated by DemoDataRules.
 */
class CatalogSeeder extends Seeder
{
    public function run(): void
    {
        $notes = FlavorNote::with('category.parent')->get();
        $namesBySubcategory = $notes->groupBy('category.slug')->map(fn (Collection $group) => $group->pluck('name')->all())->all();
        $notesByName = $notes->keyBy('name');

        foreach ($this->rows() as $row) {
            $rules = new DemoDataRules($row['cqi_ref']);
            $process = ProcessMethod::from($row['process']);
            $roast = DemoDataRules::roastLevel((float) $row['acidity'], (float) $row['body']);
            $picked = collect($rules->pickNotes($process, (float) $row['flavor'], $namesBySubcategory))
                ->map(fn (string $name) => $notesByName[$name]);
            $price250 = DemoDataRules::price250((float) $row['total_points'], $process, $row['country']);
            $origin = Origin::firstOrCreate(['country' => $row['country'], 'region' => $row['region']]);
            $name = trim($row['region'].' '.($row['variety'] ?: $process->label()));

            $attributes = [
                'origin_id' => $origin->id,
                'nickname' => DemoDataRules::nickname($this->dominantCategory($picked), $roast),
                'farm_name' => $row['farm_name'] ?: null,
                'variety' => $row['variety'] ?: null,
                'process' => $process,
                'altitude_m' => $row['altitude_m'] !== '' ? (int) $row['altitude_m'] : null,
                'roast_level' => $roast,
                'roast_date' => today()->subDays($rules->roastAgeDays()),
                'description' => $this->description($row, $process),
                'cqi_ref' => $row['cqi_ref'],
            ];

            $this->createProduct($name, ProductType::Bean, $attributes, $picked, $row, $rules, $price250);

            if ($row['drip_bag'] === '1') {
                $this->createProduct($name.' Drip Bag', ProductType::DripBag, $attributes, $picked, $row, $rules, $price250);
            }
        }
    }

    private function createProduct(string $name, ProductType $type, array $attributes, Collection $notes, array $row, DemoDataRules $rules, int $price250): void
    {
        $product = Product::create($attributes + ['name' => $name, 'slug' => $this->uniqueSlug($name), 'type' => $type]);

        $sizes = $type === ProductType::DripBag ? [BagSize::Sachet] : BagSize::forBeans();
        foreach ($sizes as $size) {
            $product->variants()->create([
                'size' => $size,
                'weight_g' => $size->grams(),
                'price' => DemoDataRules::priceFor($size, $price250),
                'stock' => $rules->stock(),
                'sku' => strtoupper("RN-{$row['cqi_ref']}-".($type === ProductType::DripBag ? 'DRIP' : $size->value)),
            ]);
        }

        $product->flavorNotes()->attach($notes->pluck('id'));

        $product->cupping()->create(collect($row)->only([
            'aroma', 'flavor', 'aftertaste', 'acidity', 'body', 'balance', 'uniformity', 'clean_cup', 'sweetness', 'cupper_points', 'total_points',
        ])->all() + ['graded_on' => $row['graded_on'] ?: null]);
    }

    /** Most frequent top-level category among the picked notes (first one wins a tie). */
    private function dominantCategory(Collection $notes): string
    {
        return $notes->countBy(fn (FlavorNote $note) => $note->category->parent->slug)->sortDesc()->keys()->first();
    }

    private function description(array $row, ProcessMethod $process): string
    {
        $parts = [
            'ล็อตจาก '.($row['farm_name'] ? $row['farm_name'].' (' : '').$row['region'].', '.$row['country'].($row['farm_name'] ? ')' : ''),
            $row['altitude_m'] !== '' ? 'ปลูกที่ความสูง '.number_format((int) $row['altitude_m']).' เมตร' : null,
            $row['variety'] ? 'สายพันธุ์ '.$row['variety'] : null,
            'แปรรูปแบบ '.$process->label(),
        ];

        return implode(' · ', array_filter($parts)).' — ผ่านการชิมให้คะแนนโดย Coffee Quality Institute ได้ '.$row['total_points'].' คะแนน';
    }

    private function uniqueSlug(string $name): string
    {
        $base = Str::slug($name);
        $slug = $base;
        for ($i = 2; Product::where('slug', $slug)->exists(); $i++) {
            $slug = "{$base}-{$i}";
        }

        return $slug;
    }

    /** @return list<array<string, string>> */
    private function rows(): array
    {
        $handle = fopen(database_path('data/cqi-selected.csv'), 'r');
        $header = fgetcsv($handle, escape: '\\');
        $rows = [];
        while (($line = fgetcsv($handle, escape: '\\')) !== false) {
            $rows[] = array_combine($header, $line);
        }
        fclose($handle);

        return $rows;
    }
}
